The listing below is the tested program. The fee for a category is held in a constant and returned by one function, so the fee rule appears once in the code exactly as it appears once in the spreadsheet's lookup table. The sentinel-controlled WHILE loop reads until end of file, which means the program still works when the club adds members and does not need a record count typed into it.

program BayviewFees;
{ Reads the club member file and prints the arrears report. }
const
  JUNIOR_FEE = 6000.0;
  SENIOR_FEE = 9500.0;
  FAMILY_FEE = 14000.0;
type
  TMember = record
    id: string[7];
    surname: string[20];
    category: char;
    amountPaid: real;
  end;
var
  f: text;
  m: TMember;
  fee, expected, paid, outstanding: real;
  memberCount, owingCount: integer;
function FeeFor(c: char): real;
begin
  case c of
    'J': FeeFor := JUNIOR_FEE;
    'S': FeeFor := SENIOR_FEE;
    'F': FeeFor := FAMILY_FEE;
  else
    FeeFor := 0.0;
  end;
end;
begin
  expected := 0.0; paid := 0.0; memberCount := 0; owingCount := 0;
  assign(f, 'members.txt');
  reset(f);
  writeln('Members with an outstanding balance');
  writeln('----------------------------------');
  while not eof(f) do
  begin
    readln(f, m.id, m.surname, m.category, m.amountPaid);
    fee := FeeFor(m.category);
    expected := expected + fee;
    paid := paid + m.amountPaid;
    memberCount := memberCount + 1;
    if m.amountPaid < fee then
    begin
      owingCount := owingCount + 1;
      writeln(m.id, '  ', m.surname, '  ', (fee - m.amountPaid):8:2);
    end;
  end;
  close(f);
  outstanding := expected - paid;
  writeln;
  writeln('Members processed : ', memberCount);
  writeln('Expected income   : ', expected:10:2);
  writeln('Fees collected    : ', paid:10:2);
  writeln('Outstanding       : ', outstanding:10:2);
  writeln('Collection rate   : ', (paid / expected * 100):6:1, ' per cent');
  writeln('Members owing     : ', owingCount);
end.
